import {PLAYERS,LEVELS,WORDS,youMark,other} from '/engine.mjs';
const $=id=>document.getElementById(id),valid=id=>Object.hasOwn(PLAYERS,id);let player=null,p=null,busy=false,botTimer,voiceEpoch=0,audio,manifest,sound=true,lastSpeech='',parentSum=15;
try{const requested=new URL(location.href).searchParams.get('player'),saved=localStorage.getItem('three-player');player=valid(requested)?requested:valid(saved)?saved:null;sound=localStorage.getItem('three-sound')!=='off';}catch{}
const event=(kind,detail)=>{if(player)void fetch('/api/events?player='+player,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,detail})}).catch(()=>{});};
async function request(path,input){const r=await fetch('/api/'+path+'?player='+player,{method:input?'POST':'GET',headers:input?{'Content-Type':'application/json'}:{},body:input?JSON.stringify(input):undefined,cache:'no-store',signal:AbortSignal.timeout(8000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not connect. Try Refresh.');return data;}
function stop(){voiceEpoch++;audio?.pause();audio=null;globalThis.speechSynthesis?.cancel();}
async function speak(line,manual=false,required=false){if(!line||(!sound&&!manual))return;globalThis.speechSynthesis?.cancel();if(!globalThis.speechSynthesis)return;const u=new SpeechSynthesisUtterance(line);u.lang='en-US';u.rate=.9;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-US'&&v.localService)||voices.find(v=>v.lang==='en-US')||null;speechSynthesis.speak(u);}
function ding(){if(!sound)return;try{const ctx=new AudioContext();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(660,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(880,ctx.currentTime+.12);g.gain.setValueAtTime(.04,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.25);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.26);o.onended=()=>void ctx.close();}catch{}}
function schedule(){clearTimeout(botTimer);if(p?.game?.phase==='bot'&&!busy&&!$('error').textContent&&document.visibilityState==='visible'&&!$('parent').open)botTimer=setTimeout(()=>void send({type:'bot'}),650);}
function render(){if(!p)return;const g=p.game,practice=g?.mode==='practice';$('name').textContent=p.name;$('you-name').textContent=p.id==='admin'?'Admin':p.name;document.title=p.name+' · Three in a Row';$('sound').textContent=sound?'♪ Sound on':'♪ Sound off';$('level').textContent=LEVELS[g?.level||p.level]+' opponent';$('progress').textContent=practice?`${p.learning.done} puzzles explored · ${p.learning.clean} solved without help`:'Three opponent strengths. Go at your own pace.';
 const mark=g?youMark(g):p.mark||'X';$('you-symbol').textContent=mark==='X'?'×':'O';$('rook-symbol').textContent=mark==='X'?'O':'×';
 $('title').textContent=practice?(g.stage==='win'?'Find your row.':g.stage==='block'?'Stop that row.':'Think ahead.'):'Three makes a team.';$('eyebrow').textContent=practice?'ONE-MOVE PRACTICE':'TIC-TAC-TOE';$('description').textContent=practice?'The board is already started. Practice uses X. Find one good move.':`You are ${mark}. Rook is ${other(mark)}. Make a row across, down, or diagonally.`;
 $('play').classList.toggle('selected',!practice);$('practice').classList.toggle('selected',!!practice);$('turn').textContent=g?.phase==='bot'?'Thinking…':g?.phase==='done'?(practice?'Nice thinking!':g.winner==='draw'?'A draw':g.winner===mark?'You win!':'Rook wins'):g?'Your turn':'Ready?';$('message').textContent=g?.message||(mark==='X'?WORDS.start:WORDS.startO);
 const board=$('board');board.replaceChildren();for(let i=0;i<9;i++){const mark=g?.board[i];const b=document.createElement('button');b.className='cell '+(mark?.toLowerCase()||'')+(g?.line.includes(i)?' win':'')+(g?.hint===i?' hint':'')+(g?.moves.at(-1)?.cell===i?' last':'');b.disabled=busy||!g||g.phase!=='you'||!!mark;b.setAttribute('aria-label',`${['Top','Middle','Bottom'][Math.floor(i/3)]} ${['left','center','right'][i%3]}: ${mark||'empty'}`);const s=document.createElement('span');s.className='mark';s.textContent=mark==='X'?'×':mark||'';b.append(s);b.onclick=()=>void send({type:'move',cell:i});board.append(b);}
 $('next').hidden=!!g&&g.phase!=='done';$('next').textContent=!g?'Let’s play →':practice?'Another puzzle →':'Play again →';$('hint').hidden=!g||g.phase==='done';$('hint').disabled=busy||g?.phase!=='you'||g?.hint!==null;$('assistance').textContent=g?.helped?'Help used · this round counts as supported practice.':p.id==='admin'?'ADMIN · Separate test save.':'';$('stats').textContent=`★ ${p.stars} stars · ${p.wins} wins · ${p.draws} draws · ${p.losses} losses · Saved on this server`;
 $('level-controls').hidden=!!practice;$('chosen-level').textContent=`Level ${p.level} · ${LEVELS[p.level]}`;
 const pending=g?.mode==='play'&&g.phase!=='done'&&g.level!==p.level;
 $('level-note').textContent=(pending?`Next match: ${LEVELS[p.level]}. This match stays ${LEVELS[g.level]}. `:'Choose your next match. ')+(p.level===3?'Perfect cannot be beaten—try for a draw.':'X goes first in every new match.');
 $('easier').disabled=busy||p.level<=1;$('harder').disabled=busy||p.level>=3;
 for(const m of ['X','O']){$('mark-'+m).disabled=busy;$('mark-'+m).setAttribute('aria-pressed',String((p.mark||'X')===m));}
 $('mark-note').textContent=g?.mode==='play'&&g.phase!=='done'&&mark!==(p.mark||'X')?`Next match: ${p.mark}. Finish this match as ${mark}.`:'Choose your next match: X goes first. O goes second.';
 for(const id of ['next','play','practice','difficulty'])$(id).disabled=busy;$('difficulty').value=String(p.level);schedule();}
async function sync(){p=await request('state');render();}
$('easier').onclick=()=>{if(p&&p.level>1)void send({type:'level',level:p.level-1});};
$('harder').onclick=()=>{if(p&&p.level<3)void send({type:'level',level:p.level+1});};
for(const mark of ['X','O'])$('mark-'+mark).onclick=()=>void send({type:'mark',mark});
async function send(input){if(busy||!p)return;busy=true;$('error').textContent='';render();const old=p;try{p=await request('action',{...input,revision:p.revision});render();if(p.game?.phase==='done'&&old.game?.phase!=='done'){if(p.game.winner!==other(youMark(p.game)))ding();void speak(p.game.message);}else if(['start','practice','mode','hint'].includes(input.type)){lastSpeech='';void speak(p.game.message);}else if(p.game?.mode==='practice'&&input.type==='move'&&p.game.phase!=='done')void speak(WORDS.retry);
 }catch(e){$('error').textContent=e.message;try{await sync();}catch{$('error').textContent='Connection lost. Your saved game is safe. Try Refresh.';}}finally{busy=false;render();}}
function choose(id){if(!valid(id)||busy)return;try{localStorage.setItem('three-player',id);}catch{}const url=new URL(location.href);url.searchParams.set('player',id);location.assign(url);}
document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>choose(b.dataset.player));$('play').onclick=()=>void send({type:'mode',mode:'play'});$('practice').onclick=()=>void send({type:'mode',mode:'practice'});$('next').onclick=()=>void send({type:p?.game?.mode==='practice'?'practice':'start'});$('hint').onclick=()=>void send({type:'hint'});$('hear').onclick=()=>void speak(p?.game?.hint!==null&&p?.game?.hint!==undefined?p.game.message:p?.game?.mode==='practice'?WORDS[p.game.stage==='win'?'find':p.game.stage]:p?.game?.phase==='done'?p.game.message:youMark(p?.game)==='O'?WORDS.startO:WORDS.start,true);
 $('sound').onclick=()=>{sound=!sound;if(!sound)stop();try{localStorage.setItem('three-sound',sound?'on':'off');}catch{}render();};$('refresh').onclick=async()=>{if(busy)return;stop();clearTimeout(botTimer);try{await request('state');const url=new URL(location.href);url.searchParams.set('v',Date.now());location.replace(url);}catch(e){$('error').textContent=e.message;}};
 $('parents').onclick=()=>{if(busy)return;stop();clearTimeout(botTimer);$('settings').hidden=true;$('gate').hidden=false;$('answer').value='';const a=5+Math.floor(Math.random()*5),b=5+Math.floor(Math.random()*5);parentSum=a+b;$('question').textContent=`What is ${a} + ${b}?`;$('parent').showModal();};$('gate').onsubmit=e=>{e.preventDefault();if(Number($('answer').value)!==parentSum){$('answer').value='';return;}$('gate').hidden=true;$('settings').hidden=false;};$('close-parent').onclick=()=>$('parent').close();$('parent').onclose=schedule;$('difficulty').onchange=()=>void send({type:'level',level:Number($('difficulty').value)});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible'){stop();clearTimeout(botTimer);}else if(player&&!busy)void sync().catch(e=>{$('error').textContent=e.message;});});window.addEventListener('online',()=>{if(player&&!busy)void sync().catch(()=>{});});window.addEventListener('error',e=>event('error',e.message));window.addEventListener('unhandledrejection',e=>event('error',String(e.reason)));
if(player){try{localStorage.setItem('three-player',player);}catch{}sync().then(()=>event('open','Three in a Row')).catch(e=>{$('error').textContent=e.message;});}else $('welcome').showModal();
try{document.modelContext?.registerTool({name:'read_tic_tac_toe_board',description:'Read the current player, board and turn without making a move.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({player:p?.name,mode:p?.game?.mode,board:p?.game?.board,turn:p?.game?.phase,level:p?.level})});}catch{}
